//! Checks against waveforms rendered by C ggwave 060aec7 (tests/vectors,
//! regenerated by tools/gen-vectors.sh). Needs no C toolchain.

mod common;

use common::*;
use ggwave::{to_i16, Decoder, Encoder, Protocol};

struct Vector {
    name: String,
    protocol: Protocol,
    fixed: Option<usize>,
    rate: f32,
    volume: u8,
    payload: Vec<u8>,
    samples: Vec<i16>,
}

fn vectors() -> Vec<Vector> {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/vectors");
    let manifest = std::fs::read_to_string(format!("{dir}/manifest.txt")).unwrap();
    let v: Vec<Vector> = manifest
        .lines()
        .filter(|l| !l.starts_with('#'))
        .map(|l| {
            let f: Vec<&str> = l.split_whitespace().collect();
            let bytes = std::fs::read(format!("{dir}/{}.i16", f[0])).unwrap();
            Vector {
                name: f[0].to_string(),
                protocol: Protocol::from_id(f[1].parse().unwrap()).unwrap(),
                fixed: Some(f[2].parse().unwrap()).filter(|&l| l != 0),
                rate: f[3].parse().unwrap(),
                volume: f[4].parse().unwrap(),
                payload: unhex(f[5]),
                samples: bytes
                    .as_chunks::<2>()
                    .0
                    .iter()
                    .map(|b| i16::from_le_bytes(*b))
                    .collect(),
            }
        })
        .collect();
    assert!(v.len() >= 24, "missing vectors");
    v
}

#[test]
fn rust_encoder_reproduces_c_waveforms() {
    for v in vectors() {
        let r = Encoder::new(params(v.fixed, 48000.0, v.rate))
            .unwrap()
            .encode(&v.payload, v.protocol, v.volume)
            .unwrap();
        let r = to_i16(&r);
        assert_eq!(r.len(), v.samples.len(), "{}", v.name);
        let max = r
            .iter()
            .zip(&v.samples)
            .map(|(&a, &b)| (a as i32 - b as i32).abs())
            .max()
            .unwrap();
        assert!(max <= 1, "{}: differs from C by {max} LSB", v.name);
    }
}

#[test]
fn rust_decoder_reads_c_waveforms() {
    for v in vectors() {
        let rate = v.rate as usize;
        for (noise, seed) in [(0.0, 0), (0.1, 1), (0.3, 2)] {
            let c: Vec<f32> = v.samples.iter().map(|&s| s as f32 / 32768.0).collect();
            let mut x = pad(&c, rate / 7, rate);
            add_noise(&mut x, noise, seed);
            let mut d = Decoder::new(params(v.fixed, v.rate, 48000.0)).unwrap();
            let got: Vec<Vec<u8>> = x.chunks(1000).filter_map(|ch| d.push(ch)).collect();
            assert!(
                got.contains(&v.payload),
                "{} noise {noise}: got {got:?}",
                v.name
            );
        }
    }
}

#[test]
fn i16_input_path() {
    let v = vectors()
        .into_iter()
        .find(|v| v.name == "p1-var-32-48000")
        .unwrap();
    let mut s = vec![0i16; 4800];
    s.extend_from_slice(&v.samples);
    s.resize(s.len() + 48000, 0);
    let mut d = Decoder::new(params(None, 48000.0, 48000.0)).unwrap();
    let got: Vec<Vec<u8>> = s.chunks(512).filter_map(|ch| d.push_i16(ch)).collect();
    assert_eq!(got, vec![v.payload]);
}
